.darma-loader-darma-b12-crane-hook { --accent: var(--loader-color, #f59e0b); --accent-2: var(--loader-secondary-color, #475569); width: var(--loader-size, 104px); height: var(--loader-size, 104px); position: relative; }
.darma-loader-darma-b12-crane-hook::before { content: ''; position: absolute; top: 12%; left: 5%; width: 90%; height: 6%; border-radius: 3px; background: linear-gradient(90deg, var(--accent), var(--accent-2)); }
.darma-loader-darma-b12-crane-hook::after { content: ''; position: absolute; top: 12%; left: 11%; width: 7%; height: 82%; border-radius: 3px; background: var(--accent-2); box-shadow: calc(var(--loader-size, 104px) * -.09) calc(var(--loader-size, 104px) * .78) 0 0 var(--accent-2), calc(var(--loader-size, 104px) * .09) calc(var(--loader-size, 104px) * .78) 0 0 var(--accent-2); }
.darma-loader-darma-b12-crane-hook .darma-loader-darma-b12-crane-hook__cable { position: absolute; top: 18%; left: 62%; width: 2.5%; height: 14%; transform-origin: top center; background: #94a3b8; animation: darma-loader-darma-b12-crane-hook-hoist calc(var(--loader-speed, 1s) * 2.6) ease-in-out infinite, darma-loader-darma-b12-crane-hook-sway calc(var(--loader-speed, 1s) * 1.3) ease-in-out infinite; }
.darma-loader-darma-b12-crane-hook .darma-loader-darma-b12-crane-hook__cable span { position: absolute; top: 100%; left: 50%; width: calc(var(--loader-size, 104px) * .2); height: calc(var(--loader-size, 104px) * .15); margin-left: calc(var(--loader-size, 104px) * -.1); border-radius: 3px; background: linear-gradient(var(--accent), var(--accent-2)); box-shadow: 0 3px 6px rgba(15, 23, 42, .28); }
@keyframes darma-loader-darma-b12-crane-hook-hoist { 0%, 100% { height: 14%; } 50% { height: 54%; } }
@keyframes darma-loader-darma-b12-crane-hook-sway { 0%, 100% { transform: rotate(-5deg); } 50% { transform: rotate(5deg); } }

